import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import { setupTestApp } from "./helpers";

// The committed OpenAPI spec (generated by packages/openapi) must describe
// exactly the routes the API serves, so the generated clients can't drift
// from the server. Regenerate it with `bun run generate`. Error codes need
// no check here: the API takes them from the same zod enums the spec does.

const { routes } = setupTestApp();

const spec = JSON.parse(
  readFileSync(new URL("../openapi.json", import.meta.url), "utf8"),
) as {
  paths: Record<string, Record<string, unknown>>;
};

const served = routes
  .map((r) => `${r.method} ${r.path.replace(/:(\w+)/g, "{$1}")}`)
  .sort();
const documented = Object.entries(spec.paths)
  .flatMap(([path, ops]) =>
    Object.keys(ops).map((m) => `${m.toUpperCase()} ${path}`),
  )
  .sort();

describe("openapi.json", () => {
  it("documents every route the API serves", () => {
    expect(served.filter((r) => !documented.includes(r))).toEqual([]);
  });

  it("documents no route the API doesn't serve", () => {
    expect(documented.filter((r) => !served.includes(r))).toEqual([]);
  });
});
